    "claims": [
      {
        "text": "This study extracts local tandem series resistance from perovskite/silicon tandem devices.",
        "anchor": "we apply a method to extract the local tandem series resistance (LTR S ), a key contributor to the performance degradation of perovskite/silicon tandem devices.",
        "evidence_type": "measurement"
      },
      {
        "text": "Finite element simulations demonstrate robustness under realistic conditions.",
        "anchor": "Finite element simulations demonstrate the robustness of the method under a range of realistic conditions, including current mismatch, low shunt resistance, and luminescence coupling effects.",
        "evidence_type": "simulation"
      },
      {
        "text": "Resistive effects account for approximately 1.9% absolute efficiency loss in a 29% tandem device.",
        "anchor": "the method reveals that approximately 1.9% absolute efficiency loss can be attributed to resistive effects.",
        "evidence_type": "inference"
      }
    ]
  },
