    "pce_champion": {
      "value": 20.3,
      "unit": "%",
      "anchor": "PSCs fabricated via sequential deposition of the inorganic scaffold demonstrate improved process repeatability and reach an efficiency of 20.3%, ranking among the highest reported efficiencies for wide‐bandgap hybrid two‐step processed PSCs."
    },
