    "t80_h": null,
    "claims": [
      {
        "text": "The work presents a fully sequential route in which CsCl and PbI2 are deposited separately.",
        "anchor": "In this work, we present a fully sequential route, wherein the inorganic materials CsCl and PbI 2 are deposited separately, allowing for facile industrial implementation as compared to the commonly codeposited inorganic scaffold.",
        "evidence_type": "measurement"
      },
      {
        "text": "Sequential deposition promotes vertical growth of PbI2 platelets with a secondary tilted orientation.",
        "anchor": "Microstructural analysis reveals a change in preferred crystal orientation of the PbI 2 platelets with codeposition resulting in horizontal growth, whereas sequential deposition promotes vertical growth with a secondary tilted orientation.",
        "evidence_type": "measurement"
      },
      {
        "text": "Sequentially deposited hybrid two-step PSCs reach an efficiency of 20.3%.",
        "anchor": "PSCs fabricated via sequential deposition of the inorganic scaffold demonstrate improved process repeatability and reach an efficiency of 20.3%, ranking among the highest reported efficiencies for wide‐bandgap hybrid two‐step processed PSCs.",
        "evidence_type": "measurement"
      }
    ]
  },
