    "claims": [
      {
        "text": "TPA-Py is employed for intergrain bulk modification of double-cation perovskite absorbers to enhance thermal stability.",
        "anchor": "In this work, a 4‐(pyridin‐4‐yl)triphenylamine (TPA‐Py) with pyridine anchor group was employed for intergrain bulk modification of double‐cation CsCH(NH 2 ) 2 PbI 3 perovskite absorbers to enhance thermal stability.",
        "evidence_type": "measurement"
      },
      {
        "text": "Bulk incorporation of TPA-Py gives a large improvement in thermal stability at 85°C under ISOS-D-2.",
        "anchor": "Notable impact of self‐assembled monolayer incorporated into the bulk of the perovskite film manifested in a huge improvement of thermal stability at 85°C (ISOS‐D‐2).",
        "evidence_type": "measurement"
      },
      {
        "text": "Devices with TPA-Py show screening of ion migration with an activation energy of 0.45 eV.",
        "anchor": "In‐depth analysis using photoinduced voltage transients and admittance spectroscopy after different stress periods revealed the screening of ion migration (0.45 eV) for devices with TPA‐Py.",
        "evidence_type": "measurement"
      }
    ]
  },
